-- S2.11 retirement compacts a settled v2 prompt to a tombstone: the replayable
-- request and the copied receipt/result/error bodies are dropped, identity,
-- both digests and the outcome disposition are kept. That single transition
-- (retired_at NULL -> NOT NULL, bodies -> NULL) is the only exemption from the
-- 0140/0141 immutability guards, and a tombstone is final afterwards.
CREATE OR REPLACE FUNCTION "guard_immutable_command_request"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.request_schema = 'maister.command.request.v2' AND (
    ROW(NEW.id, NEW.run_id, NEW.execution_assignment_id, NEW.execution_host_id,
        NEW.assignment_epoch, NEW.kind, NEW.target_session_id, NEW.created_at,
        NEW.owner_kind, NEW.owner_ref, NEW.logical_operation_key,
        NEW.request_schema, NEW.request_sha256)
    IS DISTINCT FROM
    ROW(OLD.id, OLD.run_id, OLD.execution_assignment_id, OLD.execution_host_id,
        OLD.assignment_epoch, OLD.kind, OLD.target_session_id, OLD.created_at,
        OLD.owner_kind, OLD.owner_ref, OLD.logical_operation_key,
        OLD.request_schema, OLD.request_sha256)
    OR (NEW.request_canonical_json IS DISTINCT FROM OLD.request_canonical_json
      AND NOT (OLD.retired_at IS NULL AND NEW.retired_at IS NOT NULL
        AND NEW.request_canonical_json IS NULL)))
  THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      CONSTRAINT = 'execution_commands_immutable_request',
      MESSAGE = 'admitted command request and owner are immutable';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE OR REPLACE FUNCTION guard_prompt_terminal_evidence() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  retiring boolean := OLD.retired_at IS NULL AND NEW.retired_at IS NOT NULL;
BEGIN
  IF (OLD.receipt_evidence IS NOT NULL
      AND NEW.receipt_evidence IS DISTINCT FROM OLD.receipt_evidence
      AND NOT (retiring AND NEW.receipt_evidence IS NULL))
    OR (OLD.terminal_event_id IS NOT NULL AND NEW.terminal_event_id IS DISTINCT FROM OLD.terminal_event_id)
    OR (OLD.terminal_evidence_sha256 IS NOT NULL AND (
      ROW(NEW.terminal_evidence_sha256, NEW.state, NEW.completed_at)
        IS DISTINCT FROM ROW(OLD.terminal_evidence_sha256, OLD.state, OLD.completed_at)
      OR (NEW.result IS DISTINCT FROM OLD.result AND NOT (retiring AND NEW.result IS NULL))
      OR (NEW.last_error IS DISTINCT FROM OLD.last_error AND NOT (retiring AND NEW.last_error IS NULL))
      OR (OLD.retired_at IS NOT NULL AND NEW.receipt_evidence IS DISTINCT FROM OLD.receipt_evidence)))
  THEN
    RAISE EXCEPTION 'verified prompt evidence is immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'execution_commands_immutable_terminal_evidence';
  END IF;
  RETURN NEW;
END;
$$;
